contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount) public {
        require(amount > 0);
        c.createGameItem("TestItem", "ipfs://test", false, false, 0, 0, 0); if (__ESBMC_reverted()) return;
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        bool reverted;
        c.safeTransferFrom(address(this), address(0xdead), tokenId, amount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted);
    }
}

