// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(uint256 amount) internal {
        vm.assume(amount > 0);
        try c.createGameItem("TestItem", "ipfs://test", false, false, 0, 0, 0) {} catch { return; }
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        bool reverted;
        try c.safeTransferFrom(address(this), address(0xdead), tokenId, amount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
